#pragma once
static const char wirelessPage[]=R"HTML(<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>COGS car</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef2f6;color:#152a3a;font:17px system-ui,sans-serif}main{max-width:760px;margin:auto;padding:24px}h1{margin-bottom:4px}p{line-height:1.5}.card{background:white;padding:20px;border-radius:12px;margin:18px 0}button,input{font:inherit;padding:12px;border-radius:6px;border:1px solid #8a9ba8}button{background:#145ca0;color:white;cursor:pointer;min-height:48px}button:disabled{opacity:.45;cursor:default}.actions{display:flex;flex-wrap:wrap;gap:12px}#stop{background:#b52228;flex:1;font-weight:bold}#status{white-space:pre-wrap;line-height:1.65}label{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:12px 0}input{width:130px}#message{min-height:26px;color:#9c1c22}summary{cursor:pointer;font-weight:600}small{color:#536574}fieldset{border:0;padding:0;margin:0}button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #da8d16;outline-offset:3px}
</style><main><h1>COGS car</h1><p>Line following · USB + Wi-Fi</p>
<div class="card"><div class="actions"><button id="claim">Take Wi-Fi control</button><button id="start" disabled>Start line following</button><button id="stop">STOP</button></div><p id="message" role="status" aria-live="polite"></p><small>Keep this page visible while driving. When this page owns control, closing it or losing its connection stops the car within 1.5 seconds. Stop works from either USB or Wi-Fi.</small></div>
<div class="card"><strong>Live readings</strong><div id="status">Connecting…</div><button id="release" disabled>Release control</button></div>
<div class="card"><details><summary>Tune line following</summary><p>Applying a group stops the car. Changes last until reset. Test on the track after each change.</p><div id="forms"></div></details></div>
<script>
const el=id=>document.getElementById(id);let token=0,busy=false,generation=0,snapshot=null,polling=false,queued=null;
const groups=[['LINESPEED',[['Cruise mm/s',30,600],['Turn wheel mm/s',30,400],['Correction mm/s',30,600],['Capture mm/s',30,600]],0],['LINEMOTOR',[['Reference mm/s',30,1000],['Offset PWM',0,254],['Proportional gain',0,5],['Integral gain',0,10],['Launch PWM',0,255]],4],['LINECFG',[['Reference PWM',1,255],['Minimum PWM',0,255]],9]];
const inputs=[];for(const [command,fields,offset] of groups){const form=document.createElement('form');const set=document.createElement('fieldset');set.disabled=true;
fields.forEach(([name,min,max],i)=>{const label=document.createElement('label');label.textContent=name;const input=document.createElement('input');input.type='number';input.required=true;input.min=min;input.max=max;input.step=command==='LINESPEED'||name.includes('PWM')?'1':'0.001';input.setAttribute('aria-label',name);inputs[offset+i]=input;label.append(input);set.append(label)});
const button=document.createElement('button');button.textContent='Apply '+(command==='LINESPEED'?'speeds':command==='LINEMOTOR'?'motor tuning':'PWM limits');set.append(button);form.append(set);form.addEventListener('submit',event=>{event.preventDefault();act(command+' '+fields.map((_,i)=>inputs[offset+i].value).join(' '))});el('forms').append(form)}
function controls(){el('claim').disabled=busy||!!token;el('start').disabled=busy||!token;el('release').disabled=busy||!token;document.querySelectorAll('fieldset').forEach(f=>f.disabled=busy||!token)}
function render(s){snapshot=s;el('status').textContent=`Control: ${s.owner}\n${s.mode} · ${s.state} · phase ${s.phase}\nTape L / C / R: ${[4,2,1].map(b=>s.ir&b?'TAPE':'floor').join(' / ')}\nWheel speed: ${s.speed.join(' / ')} mm/s\nMotor PWM: ${s.pwm.join(' / ')}\nLongest radio service: ${(s.radioMaxUs/1000).toFixed(2)} ms`;
inputs.forEach((input,i)=>{if(!input.dataset.loaded){input.value=s.tune[i];input.dataset.loaded='1'}})}
async function request(command,ownedToken=token,keepalive=false){const response=await fetch(command?'/command':'/status',{method:command?'POST':'GET',headers:command?{'X-Robot-Control':'1','X-Robot-Token':String(ownedToken),'Content-Type':'text/plain'}:{},body:command||undefined,cache:'no-store',signal:AbortSignal.timeout(1100),keepalive});const s=await response.json();if(!response.ok||!s.ok)throw new Error(s.owner==='USB'?'USB owns control. Disconnect its controller first.':`Command rejected: ${s.state}. Take control again if the session expired.`);return s}
async function act(command){if(polling){queued=command;return;}if(busy)return;busy=true;controls();const epoch=generation;try{const s=await request(command);if(epoch!==generation)return;token=s.token;if(command==='CLAIM')inputs.forEach(input=>delete input.dataset.loaded);render(s);el('message').textContent=command==='CLAIM'?'Wi-Fi control ready.':command.startsWith('MODE')?'Line following started.':'Command accepted.'}catch(e){if(epoch===generation){token=0;el('message').textContent=e.message+' Car stops when its lease expires.'}}finally{if(epoch===generation){busy=false;controls()}}}
async function stop(){const owned=!!token;generation++;queued=null;token=0;busy=false;controls();el('message').textContent='Sending Stop…';const epoch=generation;try{const s=await request('STOP',0,true);if(epoch===generation){render(s);el('message').textContent='Stopped.'}}catch(e){if(epoch===generation)el('message').textContent=owned?'Stop unconfirmed. This page has stopped heartbeats; its lease expires within 1.5 seconds.':'Stop unconfirmed. Use the controlling connection or disconnect motor power.'}}
el('claim').onclick=()=>act('CLAIM');el('start').onclick=()=>act('MODE LINE');el('release').onclick=()=>act('RELEASE');el('stop').onclick=stop;
async function poll(){if(!busy&&!document.hidden){polling=true;const epoch=generation;try{const s=await request(token?'HEARTBEAT':null);if(epoch===generation){if(token)token=s.token;render(s)}}catch(e){if(epoch===generation){token=0;el('message').textContent='Connection lost or session expired. Take control again before starting.'}}finally{polling=false;if(epoch===generation){controls();if(queued){const command=queued;queued=null;act(command)}}}}setTimeout(poll,token?250:1000)}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&token)stop()});window.addEventListener('pagehide',()=>{if(token)stop()});controls();poll();
</script></main></html>)HTML";
